package com.popwam.pop.data.repository

import com.popwam.pop.data.api.*
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody

class PopwamRepository(private val api:PopwamApi){
    suspend fun cards()=api.cards()
    suspend fun card(id:String)=api.card(id)
    suspend fun updateCard(id:String,status:String?=null,destinationId:String?=null)=api.updateCard(id,CardUpdateRequest(status,destinationId))
    suspend fun profiles()=api.profiles()
    suspend fun profileSelector(selected:String?=null)=api.profileSelector(selected)
    suspend fun createAdditionalProfile(body:AdditionalProfileCreateRequest)=api.createAdditionalProfile(body)
    suspend fun archiveProfile(id:String,replacementProfileId:String?)=api.archiveProfile(id,ArchiveProfileRequest(replacementProfileId))
    suspend fun profileEditor(id:String,locale:String)=api.profileEditor(id,locale)
    suspend fun mutateProfileEditor(id:String,draftRevision:Int,action:com.google.gson.JsonObject,locale:String="en")=api.mutateProfileEditor(id,ProfileEditorMutationRequest(draftRevision,action),locale=locale)
    suspend fun publishingStatus(id:String,locale:String)=api.publishingStatus(id,locale)
    suspend fun publishingAction(id:String,action:String,draftRevision:Int?=null)=api.publishingAction(id,PublishingActionRequest(action,draftRevision))
    suspend fun updatePublishingVisibility(id:String,draftRevision:Int,access:String)=api.updatePublishingVisibility(id,VisibilityUpdateRequest(draftRevision,access))
    suspend fun updatePublishingVisibilityAndSlug(id:String,draftRevision:Int,access:String,slug:String)=api.updatePublishingVisibility(id,VisibilityUpdateRequest(draftRevision,access,slug))
    suspend fun updatePublishingSlug(id:String,draftRevision:Int,slug:String)=api.updatePublishingVisibility(id,VisibilityUpdateRequest(draftRevision,slug=slug))
    suspend fun updateMediaVisibility(id:String,draftRevision:Int,mediaId:String,visibility:String)=api.updatePublishingVisibility(id,VisibilityUpdateRequest(draftRevision,media=MediaVisibilityRequest(mediaId,visibility)))
    suspend fun updateModuleVisibility(id:String,draftRevision:Int,key:String,visibility:String)=api.updatePublishingVisibility(id,VisibilityUpdateRequest(draftRevision,module=ModuleVisibilityRequest(key,visibility)))
    suspend fun createProfile(body:ProfileWriteRequest)=api.createProfile(body)
    suspend fun updateProfile(id:String,body:ProfileWriteRequest)=api.updateProfile(id,body)
    suspend fun templates()=api.templates()
    suspend fun selectTemplate(virtualCardId:String,templateId:String)=api.selectTemplate(virtualCardId,TemplateSelectionRequest(templateId))
    suspend fun googleWallet(virtualCardId:String)=api.googleWallet(virtualCardId)
    suspend fun inspectActivation(value:String)=api.inspectActivation(ActivationInspectRequest(value))
    suspend fun claim(token:String,profileId:String)=api.claim(ClaimRequest(token,profileId))
    suspend fun programmingCards()=api.programmingCards()
    suspend fun markProgrammed(id:String,uri:String)=api.markProgrammed(id,ProgramRequest("PROGRAMMED",uri))
    suspend fun markLocked(id:String,uri:String)=api.markProgrammed(id,ProgramRequest("LOCKED",uri,true,"LOCK"))
    suspend fun verifyNfc(uri:String)=api.verifyNfc(VerifyNfcRequest(uri))
    suspend fun createDestination(profileId:String,body:DestinationWriteRequest)=api.createDestination(profileId,body)
    suspend fun deleteDestination(id:String)=api.deleteDestination(id)
    suspend fun shareTargets(profileId:String,locale:String)=api.shareTargets(profileId,locale)
    suspend fun shareProducts()=api.shareProducts()
    suspend fun updateShareProduct(id:String,body:ShareProductUpdateRequest)=api.updateShareProduct(id,body)
    suspend fun inspectScratchActivation(identifier:String)=api.inspectScratchActivation(ScratchActivationInspectRequest(identifier))
    suspend fun claimScratchActivation(identifier:String,scratch:String,profileId:String,targetId:String,locale:String)=api.claimScratchActivation(ScratchActivationClaimRequest(identifier,scratch,profileId,targetId,locale))
    suspend fun uploadMedia(profileId:String,kind:String,name:String,mime:String,bytes:ByteArray,draftRevision:Int?=null)=api.uploadMedia(profileId,when(kind.lowercase()){"avatar"->"AVATAR";"cover"->"COVER";"logo"->"LOGO";else->"GALLERY"}.toRequestBody("text/plain".toMediaTypeOrNull()),draftRevision?.toString()?.toRequestBody("text/plain".toMediaTypeOrNull()),MultipartBody.Part.createFormData("file",name,bytes.toRequestBody(mime.toMediaTypeOrNull())))
    suspend fun removeEditorMedia(profileId:String,mediaId:String,draftRevision:Int)=api.removeEditorMedia(profileId,mediaId,draftRevision)
    suspend fun uploadFile(profileId:String,titleAr:String,titleEn:String,name:String,mime:String,bytes:ByteArray)=api.uploadFile(profileId,titleAr.toRequestBody("text/plain".toMediaTypeOrNull()),titleEn.toRequestBody("text/plain".toMediaTypeOrNull()),MultipartBody.Part.createFormData("file",name,bytes.toRequestBody(mime.toMediaTypeOrNull())))
    suspend fun settingsPreferences()=api.settingsPreferences()
    suspend fun updateSettingsPreference(key:String,value:String)=api.updateSettingsPreferences(com.google.gson.JsonObject().apply{addProperty(key,value)})
    suspend fun updatePrivacyPreference(key:String,value:Boolean)=api.updateSettingsPreferences(com.google.gson.JsonObject().apply{addProperty(key,value)})
    suspend fun notificationPreferences()=api.notificationPreferences()
    suspend fun quotaUsage()=api.quotaUsage()
    suspend fun requestQuotaIncrease(resource:String,requestedValue:String)=api.requestQuotaIncrease(QuotaIncreaseRequest(resource,requestedValue))
    suspend fun discovery(locale:String,query:String?=null)=api.discovery(locale,query)
    suspend fun updateNotificationPreference(key:String,value:Boolean)=api.updateNotificationPreferences(com.google.gson.JsonObject().apply{addProperty(key,value)})
    suspend fun friendsSettings(locale:String)=api.friendsSettings(locale)
    suspend fun updateFriendsSettings(body:FriendsSettingsPatchRequest)=api.updateFriendsSettings(body)
    suspend fun acceptFriendsPolicy(locale:String)=api.acceptFriendsPolicy(LocaleRequest(locale))
    suspend fun friends(locale:String,cursor:String?=null)=api.friends(locale,cursor)
    suspend fun friendRequests(locale:String,cursor:String?=null)=api.friendRequests(locale,cursor)
    suspend fun searchFriends(locale:String,query:String,cursor:String?=null)=api.searchFriends(locale,query,cursor)
    suspend fun createFriendRequest(targetKey:String,source:String,locale:String)=api.createFriendRequest(FriendRequestCreateRequest(targetKey,source,locale))
    suspend fun acceptFriendRequest(id:String,locale:String)=api.acceptFriendRequest(id,LocaleRequest(locale))
    suspend fun rejectFriendRequest(id:String,locale:String)=api.rejectFriendRequest(id,LocaleRequest(locale))
    suspend fun cancelFriendRequest(id:String)=api.cancelFriendRequest(id)
    suspend fun updateFriendPreference(key:String,favorite:Boolean?=null,muted:Boolean?=null)=api.updateFriendPreference(key,FriendPreferencePatchRequest(favorite,muted))
    suspend fun removeFriend(key:String)=api.removeFriend(key)
    suspend fun blockedUsers(locale:String)=api.blockedUsers(locale)
    suspend fun blockUser(key:String,source:String="FRIENDS",category:String?=null)=api.blockUser(BlockUserRequest(key,source,category))
    suspend fun unblockUser(id:String)=api.unblockUser(id)
    suspend fun reportUser(key:String,category:String,details:String?,locale:String,source:String="FRIENDS")=api.reportUser(ReportUserRequest(key,category,details,locale,source))
    suspend fun nearbySettings(locale:String)=api.nearbySettings(locale)
    suspend fun acceptNearbyConsent(locale:String)=api.acceptNearbyConsent(NearbyConsentRequest(locale))
    suspend fun enableNearby(latitude:Double,longitude:Double,locale:String)=api.updateNearbyPresence(locale,NearbyPresenceRequest("ENABLE",latitude,longitude))
    suspend fun refreshNearby(latitude:Double,longitude:Double,generation:Int,sessionToken:String,locale:String)=api.updateNearbyPresence(locale,NearbyPresenceRequest("REFRESH",latitude,longitude,generation,sessionToken))
    suspend fun disableNearby()=api.disableNearbyPresence()
    suspend fun nearbyResults(locale:String)=api.nearbyResults(locale)
    suspend fun securityOverview()=api.securityOverview()
    suspend fun securityDevices()=api.securityDevices()
    suspend fun securitySessions()=api.securitySessions()
    suspend fun securityPasskeys()=api.securityPasskeys()
    suspend fun stepUpOptions(purpose:String,method:String?=null,locale:String?=null)=api.stepUpOptions(StepUpRequest(purpose,method,locale))
    suspend fun verifyPasskeyStepUp(purpose:String,assertion:com.google.gson.JsonObject)=api.verifyStepUp(StepUpRequest(purpose,"PASSKEY",assertion=assertion))
    suspend fun verifyOtpStepUp(purpose:String,challengeId:String,code:String)=api.verifyStepUp(StepUpRequest(purpose,"OTP",challengeId=challengeId,code=code))
    suspend fun revokeSecuritySession(id:String,grant:String)=api.revokeSecuritySession(id,grant)
    suspend fun revokeOtherSecuritySessions(grant:String)=api.revokeOtherSecuritySessions(grant)
    suspend fun revokeAllSecuritySessions(grant:String)=api.revokeAllSecuritySessions(grant)
    suspend fun removeSecurityPasskey(id:String,grant:String)=api.removeSecurityPasskey(id,grant)
    suspend fun passkeyRegistrationOptions(grant:String)=api.passkeyRegistrationOptions(grant)
    suspend fun verifyPasskeyRegistration(response:com.google.gson.JsonObject)=api.verifyPasskeyRegistration(response)
    suspend fun reportProductLost(id:String,grant:String)=api.reportProductLost(id,grant)
    suspend fun startPhoneChange(phone:String,locale:String,grant:String)=api.startPhoneChange(PhoneChangeStartRequest(phone,locale),grant)
    suspend fun verifyPhoneChange(challengeId:String,code:String)=api.verifyPhoneChange(PhoneChangeVerifyRequest(challengeId,code))
    suspend fun requestAccountDeletion(grant:String)=api.requestAccountDeletion(grant)
}
